function global:rf-log { param([int]$Tail=8) $path="C:\RUNEFOGE_PRO\runeforge\app\data\trace\chat.log"; if(-not (Test-Path $path)){ Write-Host "[NO_TRACE] $path" -ForegroundColor Yellow; return }; Get-Content $path -Tail $Tail | ForEach-Object { try { $j=$_ | ConvertFrom-Json; $ts=([datetime]$j.ts).ToString("MM-dd HH:mm:ss"); $msg=($j.message -replace "`r|`n"," "); Write-Host ("["+$ts+"]["+$j.route+"] "+$msg) -ForegroundColor Cyan } catch {} } }
